"/api/v1/channels": {
  post: operations["ChannelsController_Create"];
};
"/api/v1/channels/{id}/verify/start": {
  post: operations["ChannelsController_StartVerify"];
};
"/api/v1/channels/{id}/verify/confirm": {
  post: operations["ChannelsController_ConfirmVerify"];
};
"/api/v1/channels/{id}": {
  delete: operations["ChannelsController_Delete"];
};

// --- ChannelsController --------------------------------------------------
ChannelsController_Create: {
  responses: {
    /** 201 — channel created; verification required before use. */
    201: {
      content: {
        "application/json": ChannelResponse;
      };
    };
    /** 400 — invalid channel type or malformed destination. */
    400: unknown;
    /** 401 — not authenticated. */
    401: unknown;
    /** 403 — lacks permission. */
    403: unknown;
  };
  requestBody: {
    content: {
      "application/json": CreateChannelRequest;
    };
  };
};
ChannelsController_StartVerify: {
  parameters: {
    path: {
      id: string;
    };
  };
  responses: {
    /** 200 — verification challenge issued. */
    200: {
      content: {
        "application/json": VerifyStartResponse;
      };
    };
    /** 400 — channel type not supported or implementation missing. */
    400: unknown;
    /** 401 — not authenticated. */
    401: unknown;
    /** 403 — lacks permission. */
    403: unknown;
    /** 404 — channel not found. */
    404: unknown;
  };
};
ChannelsController_ConfirmVerify: {
  parameters: {
    path: {
      id: string;
    };
  };
  responses: {
    /** 204 — verification confirmed; channel is now verified. */
    204: never;
    /** 400 — verification failed (wrong code or unsupported type). */
    400: unknown;
    /** 401 — not authenticated. */
    401: unknown;
    /** 403 — lacks permission. */
    403: unknown;
    /** 404 — channel not found. */
    404: unknown;
  };
  requestBody: {
    content: {
      "application/json": VerifyConfirmRequest;
    };
  };
};
ChannelsController_Delete: {
  parameters: {
    path: {
      id: string;
    };
  };
  responses: {
    /** 204 — channel deleted. */
    204: never;
    /** 401 — not authenticated. */
    401: unknown;
    /** 403 — lacks permission. */
    403: unknown;
    /** 404 — channel not found. */
    404: unknown;
  };
};

// --- Channel DTOs --------------------------------------------------------

/** Body for `POST /api/v1/channels`. */
export type CreateChannelRequest = {
  Type: string;
  Destination: string;
};

/** Response shape for `POST /api/v1/channels`. */
export type ChannelResponse = {
  Id: string;
  Type: string;
  Destination: string;
  Verified: boolean;
  CreatedAt: string;
};

/** Response shape for `POST /api/v1/channels/{id}/verify/start`. */
export type VerifyStartResponse = {
  Code: string;
};

/** Body for `POST /api/v1/channels/{id}/verify/confirm`. */
export type VerifyConfirmRequest = {
  Code: string;
};

import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { vi, describe, it, expect, beforeEach } from "vitest";
import { AddChannelDialog } from "./AddChannelDialog";

// Mock the API client
vi.mock("@/lib/api/client", () => ({
  apiClient: {
    POST: vi.fn(),
  },
}));

const mockOnSuccess = vi.fn();
const mockOnClose = vi.fn();

describe("AddChannelDialog", () => {
  let queryClient: QueryClient;

  beforeEach(() => {
    queryClient = new QueryClient({
      defaultOptions: {
        queries: { retry: false },
        mutations: { retry: false },
      },
    });
    mockOnSuccess.mockClear();
    mockOnClose.mockClear();
  });

  const render_ = (props?: Partial<React.ComponentProps<typeof AddChannelDialog>>) =>
    render(
      <QueryClientProvider client={queryClient}>
        <AddChannelDialog
          open={true}
          onClose={mockOnClose}
          onChannelCreated={mockOnSuccess}
          {...props}
        />
      </QueryClientProvider>
    );

  it("renders the dialog with channel type selection", () => {
    render_();
    expect(screen.getByRole("heading", { name: /add.*channel/i })).toBeInTheDocument();
    expect(screen.getByText(/email/i)).toBeInTheDocument();
    expect(screen.getByText(/slack/i)).toBeInTheDocument();
  });

  it("does not render when open is false", () => {
    render_({ open: false });
    expect(screen.queryByRole("heading", { name: /add.*channel/i })).not.toBeInTheDocument();
  });

  it("closes the dialog when cancel button is clicked", async () => {
    const user = userEvent.setup();
    render_();
    const cancelButton = screen.getByRole("button", { name: /cancel/i });
    await user.click(cancelButton);
    expect(mockOnClose).toHaveBeenCalled();
  });

  it("closes the dialog when ESC key is pressed", async () => {
    render_();
    fireEvent.keyDown(document, { key: "Escape" });
    expect(mockOnClose).toHaveBeenCalled();
  });

  it("allows user to select email channel and enter destination", async () => {
    const user = userEvent.setup();
    render_();

    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "test@example.com");

    expect(emailInput).toHaveValue("test@example.com");
  });

  it("allows user to select slack channel and enter webhook URL", async () => {
    const user = userEvent.setup();
    render_();

    const slackButton = screen.getByRole("button", { name: /slack/i });
    await user.click(slackButton);

    const urlInput = screen.getByPlaceholderText(/webhook.*url/i);
    await user.type(urlInput, "https://hooks.slack.com/services/T00/B00/XX");

    expect(urlInput).toHaveValue("https://hooks.slack.com/services/T00/B00/XX");
  });

  it("validates email format before submission", async () => {
    const user = userEvent.setup();
    render_();

    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "invalid-email");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/invalid email/i)).toBeInTheDocument();
    });
    expect(mockOnSuccess).not.toHaveBeenCalled();
  });

  it("validates slack URL format before submission", async () => {
    const user = userEvent.setup();
    render_();

    const slackButton = screen.getByRole("button", { name: /slack/i });
    await user.click(slackButton);

    const urlInput = screen.getByPlaceholderText(/webhook.*url/i);
    await user.type(urlInput, "not-a-url");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/invalid.*url/i)).toBeInTheDocument();
    });
    expect(mockOnSuccess).not.toHaveBeenCalled();
  });

  it("shows loading state while creating channel", async () => {
    const user = userEvent.setup();
    const { apiClient } = await import("@/lib/api/client");

    vi.mocked(apiClient.POST).mockImplementationOnce(
      () =>
        new Promise((resolve) =>
          setTimeout(() => resolve({ response: { status: 201, body: { Id: "123" } } }), 100)
        ) as any
    );

    render_();

    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "test@example.com");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    expect(submitButton).toBeDisabled();
  });

  it("transitions to verification step after channel is created", async () => {
    const user = userEvent.setup();
    const { apiClient } = await import("@/lib/api/client");

    vi.mocked(apiClient.POST).mockResolvedValueOnce({
      response: {
        status: 201,
        body: {
          Id: "channel-123",
          Type: "email",
          Destination: "test@example.com",
          Verified: false,
          CreatedAt: new Date().toISOString(),
        },
      },
    } as any);

    render_();

    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "test@example.com");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/verification.*code/i)).toBeInTheDocument();
    });
  });

  it("displays error message when channel creation fails", async () => {
    const user = userEvent.setup();
    const { apiClient } = await import("@/lib/api/client");

    vi.mocked(apiClient.POST).mockResolvedValueOnce({
      response: {
        status: 400,
        body: { error: "invalid_type" },
      },
    } as any);

    render_();

    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "test@example.com");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText(/failed.*create/i)).toBeInTheDocument();
    });
  });

  it("calls onChannelCreated after verification is confirmed", async () => {
    const user = userEvent.setup();
    const { apiClient } = await import("@/lib/api/client");

    // First call: channel creation
    vi.mocked(apiClient.POST)
      .mockResolvedValueOnce({
        response: {
          status: 201,
          body: {
            Id: "channel-123",
            Type: "email",
            Destination: "test@example.com",
            Verified: false,
            CreatedAt: new Date().toISOString(),
          },
        },
      } as any)
      // Second call: verify start
      .mockResolvedValueOnce({
        response: { status: 200, body: { Code: "123456" } },
      } as any)
      // Third call: verify confirm
      .mockResolvedValueOnce({
        response: { status: 204, body: {} },
      } as any);

    render_();

    // Step 1: Create channel
    const emailButton = screen.getByRole("button", { name: /email/i });
    await user.click(emailButton);

    const emailInput = screen.getByPlaceholderText(/enter.*email/i);
    await user.type(emailInput, "test@example.com");

    const submitButton = screen.getByRole("button", { name: /add channel/i });
    await user.click(submitButton);

    // Step 2: Enter verification code
    await waitFor(() => {
      expect(screen.getByText(/verification.*code/i)).toBeInTheDocument();
    });

    const codeInput = screen.getByPlaceholderText(/enter.*code/i);
    await user.type(codeInput, "123456");

    const confirmButton = screen.getByRole("button", { name: /confirm/i });
    await user.click(confirmButton);

    // Step 3: Verify success
    await waitFor(() => {
      expect(mockOnSuccess).toHaveBeenCalled();
    });
  });
});

"use client";

import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Stack,
  TextField,
  Alert,
  Box,
  Typography,
  CircularProgress,
} from "@mui/material";
import { z } from "zod";
import { apiClient } from "@/lib/api/client";
import { CreateChannelRequest, VerifyStartResponse } from "@/lib/api/schema";

// Zod schemas for validation
const emailChannelSchema = z.object({
  type: z.literal("email"),
  destination: z.string().email("Invalid email address"),
});

const slackChannelSchema = z.object({
  type: z.literal("slack"),
  destination: z.string().url("Invalid webhook URL"),
});

const channelSchema = z.union([emailChannelSchema, slackChannelSchema]);

type ChannelInput = z.infer<typeof channelSchema>;

type Step = "select-type" | "enter-destination" | "verify" | "success";

interface AddChannelDialogProps {
  open: boolean;
  onClose: () => void;
  onChannelCreated: () => void;
}

export function AddChannelDialog({
  open,
  onClose,
  onChannelCreated,
}: AddChannelDialogProps) {
  const [step, setStep] = useState<Step>("select-type");
  const [selectedType, setSelectedType] = useState<"email" | "slack" | null>(null);
  const [destination, setDestination] = useState("");
  const [verificationCode, setVerificationCode] = useState("");
  const [channelId, setChannelId] = useState<string | null>(null);
  const [validationError, setValidationError] = useState<string>("");
  const [apiError, setApiError] = useState<string>("");

  const createChannelMutation = useMutation({
    mutationFn: async (req: CreateChannelRequest) => {
      const result = await apiClient.POST("/api/v1/channels", { body: req });
      if (result.response.status !== 201) {
        throw new Error("Failed to create channel");
      }
      return result.response.body;
    },
    onSuccess: (channel) => {
      setChannelId(channel.Id);
      setStep("verify");
      setApiError("");
    },
    onError: () => {
      setApiError("Failed to create channel. Please try again.");
    },
  });

  const startVerifyMutation = useMutation({
    mutationFn: async () => {
      if (!channelId) throw new Error("Channel ID not set");
      const result = await apiClient.POST(
        `/api/v1/channels/{id}/verify/start`,
        { params: { path: { id: channelId } } }
      );
      if (result.response.status !== 200) {
        throw new Error("Failed to start verification");
      }
      return result.response.body as VerifyStartResponse;
    },
    onError: () => {
      setApiError("Failed to start verification. Please try again.");
    },
  });

  const confirmVerifyMutation = useMutation({
    mutationFn: async (code: string) => {
      if (!channelId) throw new Error("Channel ID not set");
      const result = await apiClient.POST(
        `/api/v1/channels/{id}/verify/confirm`,
        { params: { path: { id: channelId } }, body: { Code: code } }
      );
      if (result.response.status !== 204) {
        throw new Error("Verification failed");
      }
      return result.response.body;
    },
    onSuccess: () => {
      setStep("success");
      setApiError("");
      // Notify parent and close after a short delay
      setTimeout(() => {
        onChannelCreated();
        handleClose();
      }, 500);
    },
    onError: () => {
      setApiError("Verification failed. Please check the code and try again.");
    },
  });

  const handleClose = () => {
    setStep("select-type");
    setSelectedType(null);
    setDestination("");
    setVerificationCode("");
    setChannelId(null);
    setValidationError("");
    setApiError("");
    onClose();
  };

  const handleSelectType = (type: "email" | "slack") => {
    setSelectedType(type);
    setStep("enter-destination");
    setValidationError("");
  };

  const handleCreateChannel = async () => {
    setValidationError("");

    if (!selectedType) {
      setValidationError("Please select a channel type");
      return;
    }

    const data = { type: selectedType, destination };

    try {
      channelSchema.parse(data);
    } catch (error) {
      if (error instanceof z.ZodError) {
        setValidationError(error.errors[0].message);
      }
      return;
    }

    createChannelMutation.mutate({
      Type: selectedType,
      Destination: destination,
    });
  };

  const handleConfirmVerification = async () => {
    if (!verificationCode) {
      setValidationError("Please enter the verification code");
      return;
    }
    confirmVerifyMutation.mutate(verificationCode);
  };

  const handleBack = () => {
    if (step === "enter-destination") {
      setStep("select-type");
      setSelectedType(null);
      setDestination("");
      setValidationError("");
    } else if (step === "verify") {
      setStep("enter-destination");
      setVerificationCode("");
      setValidationError("");
    }
  };

  const isLoading =
    createChannelMutation.isPending ||
    startVerifyMutation.isPending ||
    confirmVerifyMutation.isPending;

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="sm"
      fullWidth
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          handleClose();
        }
      }}
    >
      <DialogTitle>Add a Channel</DialogTitle>
      <DialogContent>
        <Stack spacing={3} sx={{ mt: 2 }}>
          {apiError && <Alert severity="error">{apiError}</Alert>}
          {validationError && <Alert severity="error">{validationError}</Alert>}

          {step === "select-type" && (
            <Stack spacing={2}>
              <Typography variant="body2" color="text.secondary">
                Choose where you'd like to receive notifications
              </Typography>
              <Stack direction="row" spacing={2}>
                <Button
                  variant="outlined"
                  onClick={() => handleSelectType("email")}
                  fullWidth
                >
                  Email
                </Button>
                <Button
                  variant="outlined"
                  onClick={() => handleSelectType("slack")}
                  fullWidth
                >
                  Slack
                </Button>
              </Stack>
            </Stack>
          )}

          {step === "enter-destination" && (
            <Stack spacing={2}>
              <TextField
                label={selectedType === "email" ? "Email address" : "Slack webhook URL"}
                placeholder={
                  selectedType === "email"
                    ? "Enter your email address"
                    : "Enter webhook URL"
                }
                value={destination}
                onChange={(e) => {
                  setDestination(e.target.value);
                  setValidationError("");
                }}
                fullWidth
                autoFocus
              />
            </Stack>
          )}

          {step === "verify" && (
            <Stack spacing={2}>
              <Typography variant="body2" color="text.secondary">
                A verification code has been sent to {destination}. Enter it below to
                confirm.
              </Typography>
              <TextField
                label="Verification code"
                placeholder="Enter the 6-digit code"
                value={verificationCode}
                onChange={(e) => {
                  setVerificationCode(e.target.value);
                  setValidationError("");
                }}
                fullWidth
                autoFocus
              />
            </Stack>
          )}

          {step === "success" && (
            <Box sx={{ textAlign: "center", py: 2 }}>
              <Typography variant="h6">Channel verified!</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                Your channel is ready to receive notifications.
              </Typography>
            </Box>
          )}
        </Stack>
      </DialogContent>

      <DialogActions>
        {step !== "success" && (
          <>
            {(step === "enter-destination" || step === "verify") && (
              <Button onClick={handleBack} disabled={isLoading}>
                Back
              </Button>
            )}
            <Button onClick={handleClose} disabled={isLoading}>
              Cancel
            </Button>
          </>
        )}

        {step === "select-type" && <div />}

        {step === "enter-destination" && (
          <Button
            onClick={handleCreateChannel}
            variant="contained"
            disabled={isLoading || !destination}
          >
            {isLoading ? <CircularProgress size={24} /> : "Add channel"}
          </Button>
        )}

        {step === "verify" && (
          <Button
            onClick={handleConfirmVerification}
            variant="contained"
            disabled={isLoading || !verificationCode}
          >
            {isLoading ? <CircularProgress size={24} /> : "Confirm"}
          </Button>
        )}

        {step === "success" && (
          <Button onClick={handleClose} variant="contained">
            Done
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
}

