{ useState } from "react";
import Alert from "@mui/material/Alert";
import AlertTitle from "@mui/material/AlertTitle";
import Container from "@mui/material/Container";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Button from "@mui/material/Button";
import { AddChannelDialog } from "@/features/channels/AddChannelDialog";

/**
 * The post-sign-in landing page. The real
 * "alerts dashboard" with grouped lists, "test this alert" buttons,
 * and the channel-mode matrix lands in wave 4. This is the wave 4
 * stub with the Add Channel dialog integrated.
 *
 * Server Component — the auth gate runs in the parent
 * <c>(app)/layout.tsx</c> via <c>AuthGate</c>. This page is
 * server-rendered, so a returning user with a still-valid cookie
 * gets a real HTML response with the placeholder shell.
 */
export default function AlertsPage() {
  const [dialogOpen, setDialogOpen] = useState(false);

  return (
    <Container maxWidth="md" component="main">
      <Stack spacing={4} sx={{ py: { xs: 6, md: 10 } }}>
        <Stack spacing={1}>
          <Typography variant="h4" component="h1">
            Your alerts
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Manage your notification channels and configure alerts. The full
            dashboard with alert list and channel-mode matrix arrives in wave 4.
          </Typography>
        </Stack>
        <Alert severity="info">
          <AlertTitle>Wave 4 development</AlertTitle>
          The Add Channel dialog is now available. Test it by clicking the button
          below. The full dashboard with alert management arrives soon.
        </Alert>
        <Stack direction="row" spacing={2}>
          <Button variant="contained" onClick={() => setDialogOpen(true)}>
            Add Channel
          </Button>
        </Stack>
      </Stack>
      <AddChannelDialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        onChannelCreated={() => {
          setDialogOpen(false);
          // Optionally show a success message or refresh the channels list
        }}
      />
    </Container>
  );
}

